**1.2 CobolReportWriter.g4 (Complete redesign — currently generic)**

Replace the generic stub with precise ISO rules:

```antlr
reportSection
    : REPORT SECTION DOT reportDescription*
    ;

reportDescription
    : reportDescriptionEntry reportGroupEntry+
    ;

reportDescriptionEntry
    : RD reportName 
      reportDescriptionClause? DOT
    ;

reportDescriptionClause
    : isGlobalClause
    | codeClause
    | controlClause
    | pageClause
    ;

// PAGE LIMIT IS integer LINES [HEADING integer] [FIRST DETAIL integer] [LAST DETAIL integer] [FOOTING integer]
pageClause
    : PAGE LIMIT IS integerLiteral LINES?
      (HEADING integerLiteral)?
      (FIRST DETAIL integerLiteral)?
      (LAST DETAIL integerLiteral)?
      (FOOTING integerLiteral)?
    ;

// CONTROL IS/ARE {FINAL | data-name}+ (§13.18.16)
controlClause
    : CONTROL (IS | ARE)? controlItem (controlItem)*
    ;

controlItem
    : FINAL
    | dataReference
    ;

// CODE IS literal (§13.18.12)
codeClause
    : CODE IS? literal
    ;

// IS GLOBAL (§13.18.30 applies to RD as well)
isGlobalClause
    : IS? GLOBAL
    ;

// Report group description (level-01 TYPE entry + subordinate items)
reportGroupEntry
    : levelNumber reportGroupName? reportGroupType
      reportGroupClauses? DOT
    ;

reportGroupName
    : cobolWord
    | FILLER
    ;

reportGroupType
    : TYPE IS reportGroupTypeKind
    ;

reportGroupTypeKind
    : REPORT HEADING          // TYPE IS REPORT HEADING
    | PAGE HEADING            // TYPE IS PAGE HEADING
    | CONTROL HEADING (FINAL | dataReference)?  // TYPE IS CONTROL HEADING [OF data-name | FINAL]
    | DETAIL                  // TYPE IS DETAIL
    | CONTROL FOOTING (FINAL | dataReference)?  // TYPE IS CONTROL FOOTING
    | PAGE FOOTING            // TYPE IS PAGE FOOTING
    | REPORT FOOTING          // TYPE IS REPORT FOOTING
    ;

reportGroupClauses
    : reportGroupClause+
    ;

reportGroupClause
    : nextGroupClause
    | lineClause
    | pictureClause
    | usageClause              // DISPLAY or NATIONAL
    | signClause
    | justifiedClause
    | columnClause
    | blankWhenZeroClause
    | sourceClause
    | sumClause
    | valueClause
    | presentWhenClause
    | groupIndicateClause
    | occursClause
    | varyingClause
    | genericReportGroupClause
    ;

// LINE NUMBER IS integer [ON NEXT PAGE] | PLUS integer
lineClause
    : LINE NUMBER IS? 
      (integerLiteral (ON NEXT PAGE)?
       | PLUS integerLiteral)
    ;

// NEXT GROUP IS integer [ON NEXT PAGE] | PLUS integer | NEXT PAGE | NEXT RECORD
nextGroupClause
    : NEXT GROUP IS?
      (integerLiteral (ON NEXT PAGE)?
       | PLUS integerLiteral
       | NEXT PAGE
       | NEXT RECORD)
    ;

// COLUMN NUMBER IS integer (§13.18.14 report-writer format)
columnClause
    : COLUMN NUMBER IS? integerLiteral
    ;

// SOURCE IS data-reference (§13.18.53)
sourceClause
    : SOURCE IS? dataReference
    ;

// SUM data-name [OF report-name] [UPON data-name [OF report-name]]+ [, data-name ...]
// (§13.18.54 — complex multi-level summation with UPON hierarchy)
sumClause
    : SUM sumItem (sumItem)*
    ;

sumItem
    : sumAddend (sumUpon+)?
    ;

sumAddend
    : dataReference (OF reportName)?
    ;

sumUpon
    : UPON dataReference (OF reportName)?
    ;

// VALUE IS literal (§13.18.63 report-section format — not a data item)
// Only on report items with no SOURCE or SUM
valueClause
    : (VALUE | VALUES) (IS | ARE)? literal
    ;

// PRESENT WHEN condition-1 (§13.18.41)
presentWhenClause
    : PRESENT WHEN condition
    ;

// GROUP INDICATE (§13.18.28)
groupIndicateClause
    : GROUP INDICATE
    ;

// VARYING data-name FROM literal BY literal (§13.18.64 report-writer format)
varyingClause
    : VARYING dataReference FROM literal BY literal
    ;

genericReportGroupClause
    : genericClause
    ;
```

