public sealed class ReportGroupSymbol : Symbol
{
    /// Parent report this group belongs to.
    public ReportSymbol ParentReport { get; }

    /// GROUP type (REPORT HEADING, PAGE HEADING, CONTROL HEADING, DETAIL, etc.)
    public ReportGroupType Type { get; set; }

    /// For CONTROL HEADING/FOOTING: the control data-name (or null for FINAL).
    public string? ControlDataName { get; set; }

    /// Resolved control data symbol (set post-binding).
    public DataSymbol? ControlDataSymbol { get; set; }

    /// LINE clauses: list of (line-number, on-next-page-flag) pairs.
    public List<(int lineNumber, bool onNextPage)> LineNumbers { get; } = [];

    /// NEXT GROUP clause information.
    public (NextGroupKind kind, int? value, bool onNextPage)? NextGroup { get; set; }

    /// Subordinate report items (level 02+, including SOURCE/SUM/VALUE/LINE/COLUMN items).
    public List<ReportItemSymbol> Items { get; } = [];

    /// Is this group a printable body group (DETAIL, CONTROL HEADING, CONTROL FOOTING)?
    public bool IsBodyGroup => Type is ReportGroupType.Detail 
        or ReportGroupType.ControlHeading or ReportGroupType.ControlFooting;

    public ReportGroupSymbol(string name, ReportSymbol parent, int line)
        : base(name, SymbolKind.ReportGroup, line)
    {
        ParentReport = parent;
    }
}

public enum ReportGroupType
{
    ReportHeading,
    PageHeading,
    ControlHeading,
    Detail,
    ControlFooting,
    PageFooting,
    ReportFooting,
}

public enum NextGroupKind
{
    Integer,          // NEXT GROUP IS integer
    Plus,             // NEXT GROUP IS PLUS integer
    NextPage,         // NEXT GROUP IS NEXT PAGE
    NextRecord,       // NEXT GROUP IS NEXT RECORD
}
```

