    public class ReportState
    {
        public int LineCounter { get; set; }
        public int PageCounter { get; set; }
        public Dictionary<string, (decimal value, bool sizeError)> SumCounters { get; set; } = new();
        public Dictionary<string, object> PriorControls { get; set; } = new();
        public bool IsSuppressed { get; set; }
        public bool IsActive { get; set; }
    }

    /// <summary>INITIATE report-name</summary>
    public static void Initiate(string reportName)
    {
        if (_activeReports.TryGetValue(reportName, out var state))
        {
            if (state.IsActive)
                throw new CobolRuntimeException($"EC-REPORT-ACTIVE: Report {reportName} already active");
        }
        else
        {
            state = new ReportState();
            _activeReports[reportName] = state;
        }
        state.LineCounter = 0;
        state.PageCounter = 1;
        state.SumCounters.Clear();
        state.IsSuppressed = false;
        state.IsActive = true;
    }

